-- Álbum: Vhoor (BRA 50) sai da coleção por decisão do Lucas. Desativa no sorteio (quem já tem continua no inventário,
-- mas a carta some da tela) e renumera as figurinhas do Brasil que vinham depois dele (BRA 51 em diante passa a ser -1).
begin;
update brb_private.album_catalog set active=false where slug='vhoor';
on conflict (slug) do update set card=excluded.card;
commit;